static void dense_relu(f32 *out, const f32 *inp, const f32 *w, const f32 *b, int in_dim, int out_dim) {
    for (int o = 0; o < out_dim; o++) {
        f32 s = b[o];
        for (int i = 0; i < in_dim; i++) s += w[o * in_dim + i] * inp[i];
        out[o] = (s > 0.0f) ? s : 0.0f;
    }
}

static void dense_linear(f32 *out, const f32 *inp, const f32 *w, const f32 *b, int in_dim, int out_dim) {
    for (int o = 0; o < out_dim; o++) {
        f32 s = b[o];
        for (int i = 0; i < in_dim; i++) s += w[o * in_dim + i] * inp[i];
        out[o] = s;
    }
}

void nn_forward(f32 out[2], const f32 raw_8d[8]) {
    f32 h1[NN_H1_DIM];
    f32 h2[NN_H2_DIM];

    dense_relu(h1, raw_8d, fc1_weight, fc1_bias, NN_IN_DIM, NN_H1_DIM);
    dense_relu(h2, h1, fc2_weight, fc2_bias, NN_H1_DIM, NN_H2_DIM);
    dense_linear(out, h2, fc3_weight, fc3_bias, NN_H2_DIM, NN_OUT_DIM);

    out[0] = (out[0] > NN_A_MAX) ? NN_A_MAX : ((out[0] < -NN_A_MAX) ? -NN_A_MAX : out[0]);
    out[1] = (out[1] > NN_O_MAX) ? NN_O_MAX : ((out[1] < -NN_O_MAX) ? -NN_O_MAX : out[1]);
}

